33. //==================================================================================================
34. // Memory Region Type
35. //==================================================================================================
36. 
37. ///
38. /// # Description
39. ///
40. /// A type that represents the type of a memory region.
41. ///
42. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
43. #[verus_verify]
44. pub enum MemoryRegionType {
45.     /// Usable memory.
46.     Usable,
47.     /// Reserved memory.
48.     Reserved,
49.     /// Memory mapped I/O.
50.     Mmio,
51.     /// Bad memory.
52.     Bad,
53. }
54. 
55. //==================================================================================================
56. // MMIO Cache Policy
57. //==================================================================================================
58. 
59. ///
60. /// # Description
61. ///
62. /// Caching policy for MMIO memory regions. Controls the PWT (Page Write-Through) and PCD
63. /// (Page Cache Disable) bits in the page table entries that back the region.
64. ///
65. #[verus_verify(external_derive)]
66. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
67. pub struct MmioCachePolicy {
68.     /// If `true`, the page is mapped with the Write-Through attribute (PWT=1).
69.     write_through: bool,
70.     /// If `true`, caching is enabled for the page (PCD=0).
71.     cache_enabled: bool,
72. }
73. 
74. impl MmioCachePolicy {
75.     ///
76.     /// # Description
77.     ///
78.     /// Creates a new MMIO cache policy.
79.     ///
80.     /// # Parameters
81.     ///
82.     /// - `write_through`: If `true`, enables the Write-Through attribute (PWT=1).
83.     /// - `cache_enabled`: If `true`, enables caching for the page (PCD=0).
84.     ///
85.     /// # Returns
86.     ///
87.     /// A new [`MmioCachePolicy`] instance.
88.     ///
89.     pub const fn new(write_through: bool, cache_enabled: bool) -> Self {
90.         Self {
91.             write_through,
92.             cache_enabled,
93.         }
94.     }
95. 
96.     /// Uncacheable: Write-Through Enabled, Cache Disabled.
97.     pub const UNCACHEABLE: Self = Self {
98.         write_through: true,
99.         cache_enabled: false,
100.     };
101. 
102.     /// Write-Back: Write-Through Disabled, Cache Enabled.
103.     pub const WRITE_BACK: Self = Self {
104.         write_through: false,
105.         cache_enabled: true,
106.     };
107. 
108.     ///
109.     /// # Description
110.     ///
111.     /// Returns whether the Write-Through attribute is set.
112.     ///
113.     /// # Returns
114.     ///
115.     /// `true` if the page is mapped with the Write-Through attribute (PWT=1).
116.     ///
117.     pub fn write_through(&self) -> bool {
118.         self.write_through
119.     }
120. 
121.     ///
122.     /// # Description
123.     ///
124.     /// Returns whether caching is enabled.
125.     ///
126.     /// # Returns
127.     ///
128.     /// `true` if caching is enabled for the page (PCD=0).
129.     ///
130.     pub fn cache_enabled(&self) -> bool {
131.         self.cache_enabled
132.     }
133. }
134. //==================================================================================================
135. // Memory Region
136. //==================================================================================================
137. 
138. ///
139. /// # Description
140. ///
141. /// A memory region.
142. ///
143. #[verus_verify(external_derive)]
144. #[derive(Debug, Clone)]
145. pub struct MemoryRegion<T: Address> {
146.     name: String,
147.     start: T,
148.     size: usize,
149.     typ: MemoryRegionType,
150.     perm: AccessPermission,
151.     cache_policy: Option<MmioCachePolicy>,
152. }
153. 
154. impl<T: Address> MemoryRegion<T> {
155.     /// Maximum byte-length of a memory region name.
156.     const MEMORY_REGION_NAME_MAX: usize = 32;
157. 
158.     /// Creates a new memory region.
159.     pub fn new(
160.         name: &str,
161.         start: T,
162.         size: usize,
163.         typ: MemoryRegionType,
164.         perm: AccessPermission,
165.     ) -> Result<Self, Error> {
166.         // Check if name is too long (byte length).
167.         if name.len() > Self::MEMORY_REGION_NAME_MAX {
168.             let reason: &str = "memory region name is too long";
169.             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
170.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
171.         }
172. 
173.         // Check if size of the memory region is valid.
174.         if size == 0 {
175.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
176.         }
177. 
178.         // Check if memory region is too big.
179.         let start_raw_addr: usize = start.clone().into_raw_value();
180.         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
181.             Some(end_raw_addr) => end_raw_addr,
182.             None => {
183.                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
184.             },
185.         };
186. 
187.         // Check if memory region spans outside the address space.
188.         if end_raw_addr > T::max_addr() {
189.             return Err(Error::new(
190.                 ErrorCode::InvalidArgument,
191.                 "memory region spans outside the address space",
192.             ));
193.         }
194. 
195.         Ok(Self {
196.             name: name.to_string(),
197.             start,
198.             size,
199.             typ,
200.             perm,
201.             cache_policy: None,
202.         })
203.     }
204. 
205.     pub fn name(&self) -> String {
206.         self.name.clone()
207.     }
208. 
209.     /// Returns the first valid address that lies in the target memory region.
210.     // VERUS REWRITE (view-preserving clone): `self.start.clone()` -> `self.start.clone_address()`.
211.     // `Clone::clone` has no Verus spec, so the postcondition `result@ == self@.start` cannot be
212.     // discharged through the bare `Clone` supertrait. `Address::clone_address` is the required
213.     // trait method that carries the verified contract `result@ == self@` (see
214.     // src/kernel/src/hal/mem/types/address/phys.rs:277-288). Same value, same complexity as a
215.     // `Copy`; purely a view-preserving substitution for a Verus limitation.
216.     // Minimal reproducer (confirmed): a generic
217.     //   `fn f<T: Clone + View<V = int>>(x: &T) -> (r: T) ensures r@ == x@ { x.clone() }`
218.     // fails to verify ("postcondition not satisfied") because `Clone::clone` is unspecified;
219.     // replacing the body with `x.clone_address()` (the spec'd trait method) verifies
220.     // (1 verified, 0 errors).
221.     #[verus_spec(result =>
222.         ensures
223.             result@ == self@.start,
224.     )]
225.     pub fn start(&self) -> T {
226.         self.start.clone_address()
227.     }
228. 
229.     /// Returns the size of the target memory region.
230.     #[verus_spec(result =>
231.         ensures
232.             result as int == self@.size,
233.     )]
234.     pub fn size(&self) -> usize {
235.         self.size
236.     }
237. 
238.     /// Returns the type of the target memory region.
239.     pub fn typ(&self) -> MemoryRegionType {
240.         self.typ
241.     }
242. 
243.     /// Returns the permissions of the target memory region.
244.     pub fn perm(&self) -> AccessPermission {
245.         self.perm
246.     }
247. 
248.     ///
249.     /// # Description
250.     ///
251.     /// Returns the MMIO cache policy of the target memory region, if set.
252.     ///
253.     /// # Returns
254.     ///
255.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
256.     ///
257.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
258.         self.cache_policy
259.     }
260. 
261.     ///
262.     /// # Description
263.     ///
264.     /// Sets the MMIO cache policy of the target memory region.
265.     ///
266.     /// # Parameters
267.     ///
268.     /// - `policy`: The cache policy to assign.
269.     ///
270.     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
271.         self.cache_policy = Some(policy);
272.     }
273. }
274. 
275. impl<T: Address> PartialEq for MemoryRegion<T> {
276.     fn eq(&self, other: &Self) -> bool {
277.         self.name == other.name
278.             && self.start == other.start
279.             && self.size == other.size
280.             && self.typ == other.typ
281.             && self.perm == other.perm
282.             && self.cache_policy == other.cache_policy
283.     }
284. }
285. 
286. impl<T: Address> Eq for MemoryRegion<T> {}
287. 
288. impl<T: Address> PartialOrd for MemoryRegion<T> {
289.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
290.         Some(self.cmp(other))
291.     }
292. }
293. 
294. impl<T: Address> Ord for MemoryRegion<T> {
295.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
296.         self.start.cmp(&other.start)
297.     }
298. }
299. 
300. //==================================================================================================
301. // Truncated Memory Region
302. //==================================================================================================
303. 
304. ///
305. /// # Description
306. ///
307. /// A memory region that has been truncated to a multiple of a page size.
308. ///
309. #[verus_verify(external_derive)]
310. #[derive(Clone)]
311. pub struct TruncatedMemoryRegion<T: Address>(MemoryRegion<PageAligned<T>>);
312. 
313. impl<T: Address> TruncatedMemoryRegion<T> {
314.     /// Creates a new truncated memory region.
315.     pub fn new(
316.         name: &str,
317.         start: PageAligned<T>,
318.         size: usize,
319.         typ: MemoryRegionType,
320.         perm: AccessPermission,
321.     ) -> Result<Self, Error> {
322.         // Truncate the size of the memory region to a multiple of the page size.
323.         let size: usize = ::sys::mm::align_up(size, PAGE_ALIGNMENT).ok_or_else(|| {
324.             let reason: &str = "align_up overflow";
325.             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
326.             Error::new(ErrorCode::InvalidArgument, reason)
327.         })?;
328.         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
329.     }
330. 
331.     ///
332.     /// # Description
333.     ///
334.     /// Creates a new truncated MMIO memory region with an explicit cache policy.
335.     ///
336.     /// # Parameters
337.     ///
338.     /// - `name`: Name of the memory region.
339.     /// - `start`: Page-aligned start address.
340.     /// - `size`: Size of the region in bytes (rounded up to page alignment).
341.     /// - `perm`: Access permissions for the region.
342.     /// - `cache_policy`: Caching policy that controls PWT/PCD bits in page table entries.
343.     ///
344.     /// # Returns
345.     ///
346.     /// Upon successful completion, a new [`TruncatedMemoryRegion`] with type
347.     /// [`MemoryRegionType::Mmio`] is returned. Upon failure, an error is returned instead.
348.     ///
349.     pub fn new_mmio(
350.         name: &str,
351.         start: PageAligned<T>,
352.         size: usize,
353.         perm: AccessPermission,
354.         cache_policy: MmioCachePolicy,
355.     ) -> Result<Self, Error> {
356.         let mut region: Self = Self::new(name, start, size, MemoryRegionType::Mmio, perm)?;
357.         region.0.set_cache_policy(cache_policy);
358.         Ok(region)
359.     }
360. 
361.     pub fn from_memory_region(region: MemoryRegion<T>) -> Result<Self, Error> {
362.         let cache_policy: Option<MmioCachePolicy> = region.cache_policy();
363.         let start: T = region.start().align_down(PAGE_ALIGNMENT)?;
364.         let start: PageAligned<T> = PageAligned::from_address(start)?;
365.         let name: String = region.name();
366.         let size: usize = region.size();
367.         let typ: MemoryRegionType = region.typ();
368.         let perm: AccessPermission = region.perm();
369.         let mut truncated: Self = Self::new(&name, start, size, typ, perm)?;
370.         if let Some(policy) = cache_policy {
371.             truncated.0.set_cache_policy(policy);
372.         }
373.         Ok(truncated)
374.     }
375. 
376.     pub fn name(&self) -> String {
377.         self.0.name()
378.     }
379. 
380.     /// Returns the first valid address that lies in the target memory region.
381.     #[verus_spec(result =>
382.         ensures
383.             result@ == self@.start,
384.     )]
385.     pub fn start(&self) -> PageAligned<T> {
386.         self.0.start()
387.     }
388. 
389.     /// Returns the size of the target memory region.
390.     #[verus_spec(result =>
391.         ensures
392.             result as int == self@.size,
393.     )]
394.     pub fn size(&self) -> usize {
395.         self.0.size()
396.     }
397. 
398.     /// Returns the type of the target memory region.
399.     pub fn typ(&self) -> MemoryRegionType {
400.         self.0.typ()
401.     }
402. 
403.     /// Returns the permissions of the target memory region.
404.     pub fn perm(&self) -> AccessPermission {
405.         self.0.perm()
406.     }
407. 
408.     ///
409.     /// # Description
410.     ///
411.     /// Returns the MMIO cache policy of the target memory region, if set.
412.     ///
413.     /// # Returns
414.     ///
415.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
416.     ///
417.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
418.         self.0.cache_policy()
419.     }
420. }
421. 
422. impl<T: Address> PartialEq for TruncatedMemoryRegion<T> {
423.     fn eq(&self, other: &Self) -> bool {
424.         self.0 == other.0
425.     }
426. }
427. 
428. impl<T: Address> Eq for TruncatedMemoryRegion<T> {}
429. 
430. impl<T: Address> PartialOrd for TruncatedMemoryRegion<T> {
431.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
432.         Some(self.cmp(other))
433.     }
434. }
435. 
436. impl<T: Address> Ord for TruncatedMemoryRegion<T> {
437.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
438.         self.0.cmp(&other.0)
439.     }
440. }
441. 
442. impl<T: Address> core::fmt::Debug for TruncatedMemoryRegion<T> {
443.     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
444.         write!(
445.             f,
446.             "TruncatedMemoryRegion {{ name: {}, start: {:?}, size: {}, typ: {:?}, perm: {:?}, \
447.              cache_policy: {:?} }}",
448.             self.name(),
449.             self.start(),
450.             self.size(),
451.             self.typ(),
452.             self.perm(),
453.             self.cache_policy()
454.         )
455.     }
456. }
457. 
458. //==================================================================================================
459. // Standalone Functions
460. //==================================================================================================
461. 
462. impl TruncatedMemoryRegion<PhysicalAddress> {
463.     /// Attempts to create a virtual memory region from a physical memory region.
464.     pub fn from_virtual_memory_region(region: MemoryRegion<VirtualAddress>) -> Result<Self, Error> {
465.         let name: String = region.name();
466.         let start: PageAligned<PhysicalAddress> =
467.             PageAligned::from_address(PhysicalAddress::from_virtual_address(region.start())?)?;
468.         let size: usize = region.size();
469.         let typ: MemoryRegionType = region.typ();
470.         let perm: AccessPermission = region.perm();
471.         TruncatedMemoryRegion::new(&name, start, size, typ, perm)
472.     }
473. }
